const $=s=>document.querySelector(s);const storage={get(k){try{return localStorage.getItem('fondasi-order-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-order-'+k,v);return true}catch{return false}}};
const examples=[{steps:[{expr:'2 + 3 × 4',choices:['2 + 3','3 × 4'],correct:1,why:'Perkalian dikerjakan sebelum penjumlahan. 3 × 4 = 12.',wrong:'Menghitung 2 + 3 lebih dahulu akan mengubah pengelompokan. Tanpa kurung, kerjakan perkalian 3 × 4 dahulu.'},{expr:'2 + 12',choices:['2 + 12'],correct:0,why:'Sekarang hanya penjumlahan yang tersisa. 2 + 12 = 14.'}],result:'14'},{steps:[{expr:'(2 + 3) × 4',choices:['2 + 3','3 × 4'],correct:0,why:'Tanda kurung mengelompokkan 2 + 3. Nilainya 5.',wrong:'Angka 3 masih berada dalam kelompok (2 + 3). Selesaikan kelompok itu sebelum mengalikannya dengan 4.'},{expr:'5 × 4',choices:['5 × 4'],correct:0,why:'Setelah kelompok kurung selesai, 5 × 4 = 20.'}],result:'20'},{steps:[{expr:'24 ÷ 6 × 2',choices:['24 ÷ 6','6 × 2'],correct:0,why:'Pembagian dan perkalian setingkat. Dari kiri, 24 ÷ 6 = 4.',wrong:'Perkalian tidak lebih tinggi daripada pembagian. Keduanya setingkat: mulai dengan 24 ÷ 6.'},{expr:'4 × 2',choices:['4 × 2'],correct:0,why:'Lanjutkan perkalian yang tersisa. 4 × 2 = 8.'}],result:'8'},{steps:[{expr:'10 − 3 + 2',choices:['10 − 3','3 + 2'],correct:0,why:'Pengurangan dan penjumlahan setingkat. Dari kiri, 10 − 3 = 7.',wrong:'Penjumlahan tidak lebih tinggi daripada pengurangan. Keduanya setingkat: mulai dengan 10 − 3.'},{expr:'7 + 2',choices:['7 + 2'],correct:0,why:'Hitung penjumlahan yang tersisa. 7 + 2 = 9.'}],result:'9'},{steps:[{expr:'2 × (3 + (5 − 1))',choices:['2 × 3','3 + 5','5 − 1'],correct:2,why:'Mulai dari kurung terdalam. 5 − 1 = 4.',wrong:'Selesaikan kelompok yang paling dalam, yaitu (5 − 1). Bilangan di dalamnya belum boleh digabungkan dengan bagian luar.'},{expr:'2 × (3 + 4)',choices:['2 × 3','3 + 4'],correct:1,why:'Selesaikan kurung yang tersisa. 3 + 4 = 7.',wrong:'Isi kurung 3 + 4 masih menjadi satu kelompok. Hitung dahulu sebelum dikalikan 2.'},{expr:'2 × 7',choices:['2 × 7'],correct:0,why:'Terakhir, 2 × 7 = 14.'}],result:'14'},{steps:[{expr:'1/2 + 1/3 × 3/4',choices:['1/2 + 1/3','1/3 × 3/4'],correct:1,why:'Kerjakan perkalian dahulu: 1/3 × 3/4 = 3/12 = 1/4.',wrong:'Aturan urutan berlaku juga pada pecahan. Perkalian 1/3 × 3/4 didahulukan.'},{expr:'1/2 + 1/4',choices:['1/2 + 1/4'],correct:0,why:'Samakan penyebut: 2/4 + 1/4 = 3/4.'}],result:'3/4'}];let step=0;function draw(){const e=examples[Number($('#example').value)];$('#choices').replaceChildren();if(step===e.steps.length){$('#expression').textContent=e.result;$('#step-label').textContent='Contoh selesai';const p=document.createElement('p');p.className='complete-lab';p.textContent='Semua langkah selesai. Pilih contoh lain atau ulangi untuk mencoba kembali.';$('#choices').append(p);return}const s=e.steps[step];$('#expression').textContent=s.expr;$('#step-label').textContent=`Langkah ${step+1} dari ${e.steps.length}: pilih operasi berikutnya.`;s.choices.forEach((label,i)=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.addEventListener('click',()=>{if(i!==s.correct){$('#step-feedback').textContent=s.wrong;return}const next=step+1===e.steps.length?e.result:e.steps[step+1].expr;const item=document.createElement('li');item.textContent=`${s.expr} = ${next}. ${s.why}`;$('#history').append(item);$('#step-feedback').textContent='Tepat. '+s.why;step++;draw()});$('#choices').append(b)})}function reset(){step=0;$('#history').replaceChildren();$('#step-feedback').textContent='Pilih operasi yang menurutmu boleh dikerjakan lebih dahulu. Setiap langkah perlu menjaga nilai ekspresi.';draw()}$('#example').addEventListener('change',reset);$('#reset').addEventListener('click',reset);reset();
$('#check').addEventListener('click',()=>{const v=document.querySelector('[name=awal]:checked')?.value;$('#check-feedback').textContent=!v?'Pilih satu dugaan terlebih dahulu.':v==='14'?'Tepat. 3 × 4 = 12, lalu 2 + 12 = 14. Perkalian membentuk satu bagian yang dijumlahkan dengan 2.':v==='20'?'20 adalah nilai (2 + 3) × 4. Tanpa kurung, perkalian didahulukan sehingga 2 + 3 × 4 = 14.':'Coba bayangkan 2 kancing lepas dan 3 kantong yang masing-masing berisi 4 kancing. Hitung isi seluruh kantong, lalu tambahkan kancing lepas.'});
const qs=[{t:'5 + 2 × 3 = …',n:11,d:1,h:'Perkalian dikerjakan sebelum penjumlahan.',why:'5 + 6 = 11.'},{t:'(5 + 2) × 3 = …',n:21,d:1,h:'Kerjakan isi kurung dahulu.',why:'7 × 3 = 21.'},{t:'18 ÷ 3 × 2 = …',n:12,d:1,h:'Pembagian dan perkalian setingkat. Mulai dari kiri.',why:'18 ÷ 3 × 2 = 6 × 2 = 12.'},{t:'12 − 5 + 1 = …',n:8,d:1,h:'Pengurangan dan penjumlahan setingkat. Mulai dari kiri.',why:'12 − 5 + 1 = 7 + 1 = 8.'},{t:'1/2 + 1/4 × 2 = …',n:1,d:1,h:'Kalikan seperempat dengan 2 sebelum menjumlahkan.',why:'1/2 + 2/4 = 1/2 + 1/2 = 1.'},{t:'(2 + 3)/4 = …',n:5,d:4,h:'Seluruh 2 + 3 menjadi pembilang.',why:'(2 + 3)/4 = 5/4.'},{t:'−3² = … (tanda minus berada di luar pangkat)',n:-9,d:1,h:'Hitung 3² = 9, lalu terapkan tanda minus.',why:'−3² = −(3 × 3) = −9. Dengan kurung, (−3)² justru bernilai 9.'}];function parse(s){const m=s.trim().replace(/−/g,'-').match(/^([+-]?\d+)(?:\s*\/\s*([+-]?\d+))?$/);if(!m)return null;const n=Number(m[1]),d=m[2]?Number(m[2]):1;return Number.isSafeInteger(n)&&Number.isSafeInteger(d)&&d!==0&&Math.abs(n)<=1000000&&Math.abs(d)<=1000000?{n,d}:null}const solved=new Set();$('#questions').innerHTML=qs.map((q,i)=>`<div class="question"><h3>Latihan ${i+1}</h3><p>${q.t}</p><form class="number-form" data-q="${i}"><label for="answer${i}">Jawaban latihan ${i+1}, pecahan atau bilangan bulat</label><div class="answer-line"><input id="answer${i}" type="text" inputmode="text" placeholder="misalnya 3/4" required autocomplete="off" aria-describedby="feedback${i}"><button class="button">Periksa jawaban</button></div></form><p id="feedback${i}" class="feedback" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.h}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('[data-q]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.q),q=qs[i],v=parse($('#answer'+i).value),ok=v&&v.n*q.d===q.n*v.d;$('#feedback'+i).className='feedback '+(ok?'correct':'incorrect');$('#feedback'+i).textContent=!v?'Tulis bilangan bulat atau pecahan seperti -9 atau 5/4. Penyebut tidak boleh nol.':ok?'Tepat. '+q.why:'Belum tepat. Kenali pengelompokan dan operasi yang didahulukan. Gunakan petunjuk jika perlu.';if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari ${qs.length} latihan telah dijawab dengan tepat.`}));$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#reflection-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan pada peramban ini.':'Catatan belum bisa disimpan. Salin jika ingin menyimpannya.'});function complete(){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#progress').textContent='Bacaan ditandai selesai ✓'}if(storage.get('complete')==='yes')complete();$('#complete').addEventListener('click',()=>{const ok=storage.set('complete','yes');complete();$('#complete-note').textContent=ok?'Kemajuan tersimpan. Kamu boleh kembali berlatih kapan saja.':'Selesai. Kemajuan belum dapat disimpan pada peramban ini.'});
